rss.channel:
{{ site_title }}
{{ site_url }}/index.html
{{ site_tagline }}
en-gb

{% for post in posts %}


  {{ post.title }}
  {{ site_url }}{{ post.url }}
  {{ site_url }}{{ post.url }}
  {{ post.section }}
  {% if post.date %}{{ post.date | rfc822 }}{% endif %}
  {{ post.subtitle or (post.excerpt | striptags | truncate(260)) }}
  {# Flask autoescapes .xml templates, so this is entity-escaped on the way
     out and decoded by the reader's XML parser. Do not wrap it in CDATA:
     CDATA is literal, the entities would survive it and readers would show
     the tags as text. #}
  {{ post.content }}

{% endfor %}
